// Scale hierarchy: overview areas -> outdoor destinations -> local amenities.
function applyDensity(style:any) {
 const layer=(id:string)=>style.layers.find((item:any)=>item.id===id);
 const outdoors=['campsite','viewpoint','swimming','information','lodging'];
 const pois=layer('poi-icons');
 const poiBase=JSON.parse(JSON.stringify(pois));
 pois.minzoom=14;
 pois.filter=['all',['>=',['zoom'],['max',14,['coalesce',['get','min_zoom'],14]]],['!=',['get','poi_icon'],'mountain'],['!', ['in',['get','poi_icon'],['literal',outdoors]]]];
 pois.layout['icon-size']=.85;pois.layout['icon-padding']=9;
 pois.layout['text-size']=10;pois.layout['text-padding']=7;
 const outdoor={...JSON.parse(JSON.stringify(poiBase)),id:'outdoor-pois',minzoom:11,filter:['all',['in',['get','poi_icon'],['literal',outdoors]],['>=',['zoom'],['max',11,['coalesce',['get','min_zoom'],12]]]]};
 outdoor.layout['icon-size']=.9;outdoor.layout['icon-padding']=9;
 const peaks={...JSON.parse(JSON.stringify(poiBase)),id:'peak-labels',minzoom:11,filter:['all',['==',['get','poi_icon'],'mountain'],['>=',['zoom'],['max',11,['-', ['coalesce',['get','min_zoom'],14],1]]]]};
 peaks.layout['icon-size']=.9;peaks.layout['text-size']=12;peaks.layout['text-padding']=9;peaks.layout['text-optional']=false;
 peaks.paint['text-color']='#48463b';
 // Keep small subdivisions out of overview maps and reduce their local label weight.
 const places=layer('places');
 places.filter=['all',places.filter,['any',['>=',['zoom'],12],['!', ['in',['get','class'],['literal',['suburb','neighbourhood','quarter','hamlet']]]]]];
 places.layout['text-size']=['interpolate',['linear'],['zoom'],3,10,8,11,14,12,18,14];
 const index=layer('contour-index');
 if(index){index.filter=['all',['==',['get','index'],true],['==',['%', ['get','ele_ft'],['step',['zoom'],500,12,200,13,100]],0]];index.paint['line-opacity']=['interpolate',['linear'],['zoom'],11,.38,13,.58,16,.72];index.paint['line-width']=['interpolate',['linear'],['zoom'],11,.45,14,.7,18,1];}
 const minor=layer('contours');if(minor){minor.minzoom=14;minor.paint['line-opacity']=.5;minor.paint['line-width']=['interpolate',['linear'],['zoom'],14,.4,18,.7];}
 const contourLabels=layer('contour-labels');if(contourLabels){contourLabels.filter=['all',['==',['get','index'],true],['==',['%', ['get','ele_ft'],['step',['zoom'],1000,13,500,14,200,16,100]],0]];contourLabels.layout['symbol-spacing']=400;contourLabels.layout['text-size']=10;}
 layer('park-boundaries').minzoom=5;
 layer('forest-boundaries').minzoom=6;
 layer('wilderness-boundaries').minzoom=8;
 // Detailed polygons and unclipped boundary lines replace overview geometry at local zooms.
 if(style.sources.boundaries){
  const fill=layer('area-fill');fill.maxzoom=8;
  const detailFill={...fill,id:'detailed-area-fill',source:'boundaries','source-layer':'areas',minzoom:8};delete detailFill.maxzoom;
  style.layers.splice(style.layers.indexOf(fill)+1,0,detailFill);
  for(const id of ['park-boundaries','forest-boundaries','wilderness-boundaries']){
   const overview=layer(id);overview.maxzoom=8;
   const detail={...overview,id:'detailed-'+id,source:'boundaries','source-layer':'areas',minzoom:8};
   delete detail.maxzoom;
   detail.filter=['all',['==',['geometry-type'],'LineString'],['==',['get','kind'],id.replace('-boundaries','')]];
   style.layers.splice(style.layers.indexOf(overview)+1,0,detail);
  }
 }

 layer('area-fill').paint['fill-opacity']=['interpolate',['linear'],['zoom'],3,.07,7,.12,12,.08];
 const areas=layer('area-labels');areas.layout['text-size']=['interpolate',['linear'],['zoom'],3,10,7,12,11,13,15,14];areas.layout['text-max-width']=13;areas.layout['text-padding']=14;
 // MapLibre places higher symbol layers first. Protect parks and summits from town/amenity clutter.
 const trails=layer('trail-labels');
 style.layers=style.layers.filter((item:any)=>item!==areas&&item!==trails);
 style.layers.push(outdoor,areas);
 if(trails)style.layers.push(trails);
 style.layers.push(peaks);
 style.layers.push(...[{"id":"amenity-details","type":"symbol","source":"amenities","minzoom":14,"filter":["all",["==",["get","kind"],"amenity"],["any",[">=",["zoom"],15],["==",["get","group_id"],""]]],"layout":{"icon-image":["concat","poi-",["get","poi_frame"],"-",["get","poi_icon"]],"icon-size":0.85,"icon-padding":5,"text-field":["get","name"],"text-font":["Arial","sans-serif"],"text-size":10,"text-anchor":"top","text-offset":[0,1.4],"text-optional":true},"paint":{"text-color":"#374d3d","text-halo-color":"#fffdf5","text-halo-width":1.5}},{"id":"amenity-groups","type":"symbol","source":"amenities","minzoom":10,"maxzoom":15,"filter":["all",["==",["get","kind"],"group"],[">=",["zoom"],["max",["coalesce",["get","min_zoom"],10],["case",["in",",",["get","grid_image"]],10,13]]]],"layout":{"icon-image":["get","grid_image"],"icon-padding":12,"icon-allow-overlap":false,"text-field":["get","name"],"text-font":["Arial","sans-serif"],"text-size":11,"text-max-width":12,"text-anchor":"top","text-offset":["get","text_offset"],"text-padding":6,"text-optional":false},"paint":{"text-color":"#304e3b","text-halo-color":"#fffdf5","text-halo-width":1.7}}]);
 // Keep the cluster handoff in layer zoom ranges: vector features are filtered at
 // source tile zoom (max 14), so a zoom >= 15 feature filter discards members.
 const amenityDetails=layer('amenity-details');
 amenityDetails.layout['icon-image']=['coalesce',['get','grid_image'],amenityDetails.layout['icon-image']];
 amenityDetails.filter=['all',['==',['get','kind'],'amenity'],['==',['coalesce',['get','group_id'],''],'']];
 style.layers.push({...amenityDetails,id:'amenity-group-members',minzoom:15,layout:{...amenityDetails.layout,'icon-allow-overlap':true,'icon-padding':1,'icon-size':['interpolate',['linear'],['zoom'],15,.65,16,.85]},filter:['all',['==',['get','kind'],'amenity'],['!=',['coalesce',['get','group_id'],''],'']]});
 for(const item of style.layers){if(item['source-layer']==='poi'){const covered=['information','toilet','parking','viewpoint','drinking-water','restaurant','campsite','picnic-site','shop','museum','lodging','swimming','cafe','hospital'];if(style.sources.amenities.type==='vector')item.filter=['all',item.filter,['!', ['in',['get','poi_icon'],['literal',covered]]]];else item.filter=['all',item.filter,["!",["all",["within",{"type":"Polygon","coordinates":[[[-119.69,37.7],[-119.53,37.7],[-119.53,37.78],[-119.69,37.78],[-119.69,37.7]]]}],["in",["get","poi_icon"],["literal",["information","toilet","parking","viewpoint","drinking-water","restaurant","campsite","picnic-site","shop","museum","lodging","swimming","cafe","hospital"]]]]]];}}
 if(style.sources.amenities.type==='vector'){
  for(const item of style.layers){
   if(item.source==='amenities'){item['source-layer']='amenities';if(item.id==='amenity-groups')item.layout['text-offset']=['match',['get','grid_rows'],1,['literal',[0,1.35]],2,['literal',[0,2.35]],3,['literal',[0,3.35]],['literal',[0,4.35]]];}
  }
 }
 // Water names take priority over nearby facility labels, without forcing overlap.
 const lakeLabels=style.layers.filter((item:any)=>item.id==='lake-labels'||item.id==='lake-labels-horizontal');
 style.layers=style.layers.filter((item:any)=>!lakeLabels.includes(item));
 style.layers.push(...lakeLabels);
 return style;
}

