  const colors={forest:'#ccdab9',scrub:'#e0e3bd',grass:'#e8ebca',wetland:'#cbded0',farmland:'#eee4bd',rock:'#e3ded4',ice:'#eaf2f1',developed:'#e8dfd6'};
