  style.layers.push({...detail,id:'ranked-peaks',minzoom:6,filter:['all',['==',['get','kind'],'summit'],['>=',['zoom'],['coalesce',['get','label_minzoom'],13]]],layout:{...detail.layout,'icon-size':['interpolate',['linear'],['zoom'],6,.65,11,.8,15,.9],'icon-padding':6,'text-size':['interpolate',['linear'],['zoom'],6,11,11,12,15,13],'text-optional':false,'text-variable-anchor':['top','bottom','left','right'],'text-radial-offset':.8,'text-justify':'auto','text-padding':10},paint:{...detail.paint,'text-color':'#48463b'}});
  const areaLabel=style.layers.find((l:any)=>l.id==='area-labels');if(areaLabel){style.layers=style.layers.filter((l:any)=>l!==areaLabel);areaLabel.layout['text-variable-anchor']=['center'];areaLabel.layout['text-radial-offset']=0;style.layers.splice(style.layers.findIndex((l:any)=>l.id==='ranked-peaks')+1,0,areaLabel);}
  const groups=style.layers.find((l:any)=>l.id==='amenity-groups');if(groups){groups.layout['icon-size']=['interpolate',['linear'],['zoom'],10,.72,13,.85,14,.95];groups.layout['icon-padding']=16;groups.layout['text-padding']=9;}

